function OpenInExcel(){
 try
 {
 // Get Record ID of current record user is viewing
 var parentId = Xrm.Page.data.entity.getId();
 // Remove curly braces from start and end
 parentId = parentId.substring(1, parentId.length - 1);
 // Get Host URL
 var hostUrl = Xrm.Page.context.getClientUrl();
 // XAE App unique Id, open App record from Advanced Search and copy Unique Id (Unique Id is Attribute on App Entity) field value here
 // Do not use RecordId here
 var appId = "17776ae9-dec3-4781-9111-5c0f0c472ebb"
 var sessionId = "";
 var urlVal = ('xauthorforexcel:export '+ appId + ' ' + parentId + ' ' + sessionId + ' ' + hostUrl );
 window.top.location.href =urlVal;
 }
 catch(err)
 {
 alert(err.message);
 }
}
